describe('Mobile Hamburger Menu Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should open and close the hamburger menu correctly on mobile view', () => {
    // Intercept API calls to prevent race conditions
    cy.intercept('GET', '/api/menu-items').as('getMenuItems');
    cy.wait('@getMenuItems');

    // Set viewport to mobile size
    cy.viewport('iphone-x');

    // Click the hamburger menu button
    cy.get('[data-testid="hamburger-menu-button"]').click();

    // Verify menu is visible
    cy.get('[data-testid="mobile-menu"]').should('be.visible');

    // Verify menu items are displayed
    cy.get('[data-testid="menu-item-home"]').should('be.visible');
    cy.get('[data-testid="menu-item-about"]').should('be.visible');

    // Click the close button (or hamburger button again)
    cy.get('[data-testid="close-menu-button"]').click();

    // Verify menu is closed
    cy.get('[data-testid="mobile-menu"]').should('not.exist');
  });

  it('should handle menu open/close with edge cases like multiple clicks and empty state', () => {
    // Set viewport to mobile size
    cy.viewport('iphone-12');

    // Open menu
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');

    // Click close button multiple times - should only close once
    cy.get('[data-testid="close-menu-button"]').click();
    cy.get('[data-testid="close-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('not.exist');

    // Open menu again
    cy.get('[data-testid="hamburger-menu-button"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');

    // Verify menu items are still present
    cy.get('[data-testid="menu-item-home"]').should('be.visible');

    // Click on a menu item to navigate
    cy.get('[data-testid="menu-item-about"]').click();

    // Verify menu closes after navigation
    cy.get('[data-testid="mobile-menu"]').should('not.exist');

    // Verify navigation occurred
    cy.url().should('include', '/about');
  });
});
